INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1080661, 130699, 16648, '<td valign="top">Are you brave or ignorant? Non electronic was in the challenge description, and here is a DIS coilpack on a newer car...see what position you put me in?  ONe theory is on non-meeting pics, challange wise, use a 1-5 scale...so i will. Good luck.</td>', 'Are you brave or ignorant? Non electronic was in the challenge description, and here is a DIS coilpack on a newer car...see what position you put me in?  ONe theory is on non-meeting pics, challange wise, use a 1-5 scale...so i will. Good luck.', '2004-12-29 00:05:09.000000', NULL, 1),
(1080664, 130462, 16648, '<td valign="top">This will probably do well - i have seen a similar pic before. It was a closer crop - and a better pic. The two thigs that junp out at me as distracting are the red idler gear and the out of focus words on the frame. otherwise, well done.</td>', 'This will probably do well - i have seen a similar pic before. It was a closer crop - and a better pic. The two thigs that junp out at me as distracting are the red idler gear and the out of focus words on the frame. otherwise, well done.', '2004-12-29 00:06:54.000000', NULL, 1),
(1080667, 131301, 16648, '<td valign="top">nice and sharp, but the lighting needs to show off the spinning spokes more.</td>', 'nice and sharp, but the lighting needs to show off the spinning spokes more.', '2004-12-29 00:07:46.000000', NULL, 1),
(1080669, 130318, 16648, '<td valign="top">i like the color. dislike the angle. really dislike the border thingy - uneven, too thick on the sides and the pic seems small overall.</td>', 'i like the color. dislike the angle. really dislike the border thingy - uneven, too thick on the sides and the pic seems small overall.', '2004-12-29 00:08:26.000000', NULL, 1),
(1080671, 131246, 14735, '<td valign="top">The great gear is a great shot</td>', 'The great gear is a great shot', '2004-12-29 00:08:38.000000', NULL, 1),
(1080676, 131280, 17384, '<td valign="top">Magnifico.</td>', 'Magnifico.', '2004-12-29 00:09:46.000000', NULL, 1),
(1080677, 131291, 16648, '<td valign="top">I see the idea here. but it needs more work. the leaf on the pedal? the front tire needs turned strait or use DOF to throw the wheel out of focus.</td>', 'I see the idea here. but it needs more work. the leaf on the pedal? the front tire needs turned strait or use DOF to throw the wheel out of focus.', '2004-12-29 00:10:25.000000', NULL, 1),
(1080678, 131312, 17384, '<td valign="top">Lovely. I''d like a print of this.</td>', 'Lovely. I''d like a print of this.', '2004-12-29 00:10:58.000000', NULL, 1),
(1080679, 131210, 3724, '<td valign="top">hard to see the sprokets - looks like road gear to me......</td>', 'hard to see the sprokets - looks like road gear to me......', '2004-12-29 00:11:03.000000', NULL, 1),
(1080681, 131222, 16648, '<td valign="top">Needs slightly more DOF. THe sprocket and singarm pivot should be in focus. the footpeg shold not be tthere - unbolt it next time if need be.</td>', 'Needs slightly more DOF. THe sprocket and singarm pivot should be in focus. the footpeg shold not be tthere - unbolt it next time if need be.', '2004-12-29 00:12:09.000000', NULL, 1),
(1080683, 130608, 16648, '<td valign="top">WAY TOO SMALL. Please check the tutorials on this site on how to resize a pic for entry. DPI can be ignored, it is for printing only.</td>', 'WAY TOO SMALL. Please check the tutorials on this site on how to resize a pic for entry. DPI can be ignored, it is for printing only.', '2004-12-29 00:13:15.000000', NULL, 1),
(1080684, 130501, 16648, '<td valign="top">Needs to be bigger - too hard to see the detials here.</td>', 'Needs to be bigger - too hard to see the detials here.', '2004-12-29 00:14:04.000000', NULL, 1),
(1080686, 131220, 30300, '<td valign="top">Great shot love the composition.</td>', 'Great shot love the composition.', '2004-12-29 00:15:36.000000', NULL, 1),
(1080687, 131153, 30300, '<td valign="top">Really good shsot.  Great in BW</td>', 'Really good shsot.  Great in BW', '2004-12-29 00:16:12.000000', NULL, 1),
(1080689, 130856, 16648, '<td valign="top">Needs elelctronics to operate. Therefore, does not meet challenge. I like trains and train pics...this is a different view thtn teh traditional - based on sizing of the elements in the picture, ieach is given equal weight (ballanst, loco, trees, hillside and even the rail ) This ''balance'' is not traditional - usually the element you want me to focus on is largest or otherwise pointed to by the composition. In this case the composition fails.</td>', 'Needs elelctronics to operate. Therefore, does not meet challenge. I like trains and train pics...this is a different view thtn teh traditional - based on sizing of the elements in the picture, ieach is given equal weight (ballanst, loco, trees, hillside and even the rail ) This ''balance'' is not traditional - usually the element you want me to focus on is largest or otherwise pointed to by the composition. In this case the composition fails.', '2004-12-29 00:17:06.000000', NULL, 1),
(1080693, 131220, 16648, '<td valign="top">does not appear sharp to me. has potential though.</td>', 'does not appear sharp to me. has potential though.', '2004-12-29 00:18:23.000000', NULL, 1),
(1080710, 131199, 27293, '<td valign="top">But this is just a repeat of an entry from a previous challenge... if it was an improvement of that image, or a clever play, or something, it would have been cool. Plus, a few technical deficiencies...</td>', 'But this is just a repeat of an entry from a previous challenge... if it was an improvement of that image, or a clever play, or something, it would have been cool. Plus, a few technical deficiencies...', '2004-12-29 00:24:16.000000', NULL, 1),
