(1080715, 130450, 27735, '<td valign="top">What is this, a fountain?</td>', 'What is this, a fountain?', '2004-12-29 00:26:17.000000', NULL, 1),
(1080717, 131317, 16301, '<td valign="top">aha now I get it, great idea :)</td>', 'aha now I get it, great idea :)', '2004-12-29 00:26:35.000000', NULL, 1),
(1080721, 131219, 28003, '<td valign="top">It''s fairly dull. It''s blurred due to camera shake. I guess it''s *sort of* mechanical.</td>', 'It''s fairly dull. It''s blurred due to camera shake. I guess it''s *sort of* mechanical.', '2004-12-29 00:27:36.000000', NULL, 1),
