(1080742, 130894, 23478, '<td valign="top">Nice shot, maybe stopped motion would have been better.</td>', 'Nice shot, maybe stopped motion would have been better.', '2004-12-29 00:32:43.000000', NULL, 1),
(1080743, 131185, 4859, '<td valign="top">Good idea to put this in black and white.  I really appreciate how nice cameras have become whenever I try to work with something this old.</td>', 'Good idea to put this in black and white.  I really appreciate how nice cameras have become whenever I try to work with something this old.', '2004-12-29 00:32:47.000000', NULL, 1),
