(1080748, 131243, 23478, '<td valign="top">Very nice, I think that maybe editing out the trees in the background or an angle where there is not so much going on behind the pump would have worked better.</td>', 'Very nice, I think that maybe editing out the trees in the background or an angle where there is not so much going on behind the pump would have worked better.', '2004-12-29 00:34:32.000000', NULL, 1),
(1080750, 131349, 4859, '<td valign="top">I like the photo, but I think it is a stretch (no pun intended) to put it in the Mechanical category.</td>', 'I like the photo, but I think it is a stretch (no pun intended) to put it in the Mechanical category.', '2004-12-29 00:34:45.000000', NULL, 1),
