(1080773, 130219, 15511, '<td valign="top">Actually, not very simple at all - alloy frame, progressive rate suspension, way modern, way mechanical, nice composition.</td>', 'Actually, not very simple at all - alloy frame, progressive rate suspension, way modern, way mechanical, nice composition.', '2004-12-29 00:40:27.000000', NULL, 1),
(1080774, 130822, 23478, '<td valign="top">This seems out of focus.</td>', 'This seems out of focus.', '2004-12-29 00:40:57.000000', NULL, 1),
