(1080778, 131216, 23478, '<td valign="top">Nice photo, the detail is very good.</td>', 'Nice photo, the detail is very good.', '2004-12-29 00:41:38.000000', NULL, 1),
(1080779, 130716, 23478, '<td valign="top">I like this, great color and very original idea.</td>', 'I like this, great color and very original idea.', '2004-12-29 00:42:42.000000', NULL, 1),
(1080783, 130812, 23478, '<td valign="top">Nice shot, maybe it would have more impact cropping the photo to emphasis the hinge more.</td>', 'Nice shot, maybe it would have more impact cropping the photo to emphasis the hinge more.', '2004-12-29 00:43:52.000000', NULL, 1),
(1080785, 130559, 4859, '<td valign="top">The overall tone of the photo appeals to me.  It is like sepia almost.  The line where the background joins the table doesn''t feel right to me.  It needs to be further up or down.r</td>', 'The overall tone of the photo appeals to me.  It is like sepia almost.  The line where the background joins the table doesn''t feel right to me.  It needs to be further up or down.r', '2004-12-29 00:44:11.000000', NULL, 1),
(1080789, 131307, 23478, '<td valign="top">technically a great photo, the angle and lighting add interest, I like the simplicity here.</td>', 'technically a great photo, the angle and lighting add interest, I like the simplicity here.', '2004-12-29 00:45:41.000000', NULL, 1),
(1080790, 130108, 23478, '<td valign="top">This image seems slightly OOF.</td>', 'This image seems slightly OOF.', '2004-12-29 00:46:06.000000', NULL, 1),
