(1080792, 131290, 25700, '<td valign="top">Overall a good shot, but I didn''t know what it was until I read the title, like the b&amp;W</td>', 'Overall a good shot, but I didn''t know what it was until I read the title, like the b&W', '2004-12-29 00:46:51.000000', NULL, 1),
(1080793, 131304, 23478, '<td valign="top">A bit too dark.</td>', 'A bit too dark.', '2004-12-29 00:47:00.000000', NULL, 1),
