(1080796, 130961, 4859, '<td valign="top">Kind of morbid, but well done.  It jolted me a bit when I first looked at the photo.  The off balance layout feeds the feeling that something is wrong here.  Even though I felt disturbed viewing the photograph, I think it is excellent.</td>', 'Kind of morbid, but well done.  It jolted me a bit when I first looked at the photo.  The off balance layout feeds the feeling that something is wrong here.  Even though I felt disturbed viewing the photograph, I think it is excellent.', '2004-12-29 00:47:27.000000', NULL, 1),
(1080798, 131301, 23478, '<td valign="top">Excellent photo.</td>', 'Excellent photo.', '2004-12-29 00:48:00.000000', NULL, 1),
(1080801, 131360, 4859, '<td valign="top">If you had not described where this came from I never would have guessed it.  Nice colors, interesting layout, and the highlight on the water relfection is really effective.</td>', 'If you had not described where this came from I never would have guessed it.  Nice colors, interesting layout, and the highlight on the water relfection is really effective.', '2004-12-29 00:48:47.000000', NULL, 1),
(1080802, 130428, 25700, '<td valign="top">Nice touch with the selective desaturation...helps to show this machines function</td>', 'Nice touch with the selective desaturation...helps to show this machines function', '2004-12-29 00:48:49.000000', NULL, 1),
(1080803, 130970, 23478, '<td valign="top">NIce shot.</td>', 'NIce shot.', '2004-12-29 00:49:22.000000', NULL, 1),
(1080806, 131304, 25700, '<td valign="top">Very dramatic indeed! Just wish the subject was a bit more clear. But, the shadows are great.</td>', 'Very dramatic indeed! Just wish the subject was a bit more clear. But, the shadows are great.', '2004-12-29 00:49:58.000000', NULL, 1),
(1080807, 131314, 4859, '<td valign="top">Nice black and white, especially the strongly highlighted spring.  It makes me think of some weird alien lifeforce, especially with the strange landscape.  Well done.</td>', 'Nice black and white, especially the strongly highlighted spring.  It makes me think of some weird alien lifeforce, especially with the strange landscape.  Well done.', '2004-12-29 00:50:07.000000', NULL, 1),
(1080808, 131281, 23478, '<td valign="top">Nice angle.</td>', 'Nice angle.', '2004-12-29 00:50:16.000000', NULL, 1),
(1080809, 131219, 23478, '<td valign="top">Nice idea, this just =needs to be focused better.</td>', 'Nice idea, this just =needs to be focused better.', '2004-12-29 00:50:56.000000', NULL, 1),
(1080810, 130428, 4859, '<td valign="top">I''m tryiing to figure out if you desaturated the photo except for the paper, or was this really the way you shot it.  Very effective.  Nice layout.</td>', 'I''m tryiing to figure out if you desaturated the photo except for the paper, or was this really the way you shot it.  Very effective.  Nice layout.', '2004-12-29 00:51:19.000000', NULL, 1),
(1080811, 130262, 22734, '<td valign="top">A great diagonal composition with sepia to give it that extra grit. Good textures and good focus.</td>', 'A great diagonal composition with sepia to give it that extra grit. Good textures and good focus.', '2004-12-29 00:51:37.000000', NULL, 1),
