(1081295, 130639, 27342, '<td valign="top">nice shot. This would have been a good time to use the rule of thirds.  At least for the placement of the subject.  Still a really nice shot.</td>', 'nice shot. This would have been a good time to use the rule of thirds.  At least for the placement of the subject.  Still a really nice shot.', '2004-12-29 10:24:43.000000', NULL, 1),
