(1081304, 130811, 3724, '<td valign="top">Nice sharp interesting oxidized metal detail....... touch of snow adds .</td>', 'Nice sharp interesting oxidized metal detail....... touch of snow adds .', '2004-12-29 10:28:07.000000', NULL, 1),
(1081308, 131280, 3724, '<td valign="top">Face reflection eminating from the machine is arresting.   Great conception, and well made.</td>', 'Face reflection eminating from the machine is arresting.   Great conception, and well made.', '2004-12-29 10:35:53.000000', NULL, 1),
(1081310, 130476, 20679, '<td valign="top">Not sure how many people know the difference between a tracker action and pneumatic action organ so this may be lost on some! However, as an organist with a great affection for trackers, I can appreciate your shot. Purists will say that unless the bellows are operated by hand, the electric blower would disqualify this shot, but I think the organ is a miracle of mechanics - which actually provides the challenge musically!  Photographically, the flare on the pipes is rather distracting (presumably from the flash) A tripod and slow shutter speed would have created a more pleasing picture, although churches are hard to expose correctly without some fill light.</td>', 'Not sure how many people know the difference between a tracker action and pneumatic action organ so this may be lost on some! However, as an organist with a great affection for trackers, I can appreciate your shot. Purists will say that unless the bellows are operated by hand, the electric blower would disqualify this shot, but I think the organ is a miracle of mechanics - which actually provides the challenge musically!  Photographically, the flare on the pipes is rather distracting (presumably from the flash) A tripod and slow shutter speed would have created a more pleasing picture, although churches are hard to expose correctly without some fill light.', '2004-12-29 10:37:50.000000', NULL, 1),
(1081320, 131274, 8139, '<td valign="top">Nice DOF</td>', 'Nice DOF', '2004-12-29 10:43:40.000000', NULL, 1),
(1081336, 130639, 26505, '<td valign="top">This is great! I really like the simple mechanics set against the beauty of the sky!</td>', 'This is great! I really like the simple mechanics set against the beauty of the sky!', '2004-12-29 10:49:55.000000', NULL, 1),
(1081339, 131120, 20679, '<td valign="top">nice shot although would have been stronger with pasta actually coming out of the machine!</td>', 'nice shot although would have been stronger with pasta actually coming out of the machine!', '2004-12-29 10:51:22.000000', NULL, 1),
(1081366, 131349, 3102, '<td valign="top">A great shot... cool lighting... a little bit of a stretch for the challenge, though. - 7</td>', 'A great shot... cool lighting... a little bit of a stretch for the challenge, though. - 7', '2004-12-29 11:12:09.000000', NULL, 1),
