(1081515, 131168, 21714, '<td valign="top">Nicely balanced lighting with beautiful tones and fine details create this beautiful shot.  I like the arrangment too. Well done.</td>', 'Nicely balanced lighting with beautiful tones and fine details create this beautiful shot.  I like the arrangment too. Well done.', '2004-12-29 12:44:43.000000', NULL, 1),
(1081522, 130893, 21714, '<td valign="top">Great composition that makes you feel that there''s a lot of stress on the frame itself.  I like it a lot, but I also feel that it could be improved by using a wide angle lens closer to the lens for greater impact. Nice job.</td>', 'Great composition that makes you feel that there''s a lot of stress on the frame itself.  I like it a lot, but I also feel that it could be improved by using a wide angle lens closer to the lens for greater impact. Nice job.', '2004-12-29 12:47:07.000000', NULL, 1),
(1081528, 130961, 21714, '<td valign="top">Would look great on an album cover or campaign poster. Unique image shot and presented beautifully. The edges look bit odd but still the image does not loose the impact from that.</td>', 'Would look great on an album cover or campaign poster. Unique image shot and presented beautifully. The edges look bit odd but still the image does not loose the impact from that.', '2004-12-29 12:49:38.000000', NULL, 1),
(1081535, 130462, 21714, '<td valign="top">Because of elements and composition of the image, I think greater depth of field (through out the image) would enhance the impact.</td>', 'Because of elements and composition of the image, I think greater depth of field (through out the image) would enhance the impact.', '2004-12-29 12:54:30.000000', NULL, 1),
