(1082254, 130316, 31244, '<td valign="top">Nice picture, a little stark as a whole and theres a distracting brown spot at the bottom.</td>', 'Nice picture, a little stark as a whole and theres a distracting brown spot at the bottom.', '2004-12-29 19:45:51.000000', NULL, 1),
