(1082656, 131153, 30861, '<td valign="top">Lacking critical sharpness, lacking richness and detail in the dark areas. Still, a nice "brutalist" image.</td>', 'Lacking critical sharpness, lacking richness and detail in the dark areas. Still, a nice "brutalist" image.', '2004-12-30 02:29:41.000000', NULL, 1),
(1082657, 130360, 30861, '<td valign="top">I want tolike this more than I do. The composition is sweet, but for this image to work well it has to be sharp as a tack, and it''s far from that.</td>', 'I want tolike this more than I do. The composition is sweet, but for this image to work well it has to be sharp as a tack, and it''s far from that.', '2004-12-30 02:30:38.000000', NULL, 1),
(1082659, 130778, 30861, '<td valign="top">Image seems too contrasty and "down" in tone in the subject areas. Cropping on bottom is unfortunate, and the framing (angle of rifle, primarily, is indifferent. Subject matter is appealing.</td>', 'Image seems too contrasty and "down" in tone in the subject areas. Cropping on bottom is unfortunate, and the framing (angle of rifle, primarily, is indifferent. Subject matter is appealing.', '2004-12-30 02:32:23.000000', NULL, 1),
