(1082662, 131348, 30861, '<td valign="top">I''d like to see this without the background and foreground distractions. Conceprtually appealing.</td>', 'I''d like to see this without the background and foreground distractions. Conceprtually appealing.', '2004-12-30 02:34:52.000000', NULL, 1),
(1082664, 131293, 30861, '<td valign="top">appealing in a sad, chaotic way. The strong central element seems oddly right. It doesn''t seem sharp, and it needs to be.</td>', 'appealing in a sad, chaotic way. The strong central element seems oddly right. It doesn''t seem sharp, and it needs to be.', '2004-12-30 02:36:06.000000', NULL, 1),
(1082665, 131324, 30861, '<td valign="top">an odd "drift" on the points of critical focus; wheel rim, foreground gear, metal hoop top right, part of the support bat appended thereto. The strongest visual element here is the trunctaed wheel. It''s an appealing image in many ways, but ultimately confusing and haphazard feeling to me.</td>', 'an odd "drift" on the points of critical focus; wheel rim, foreground gear, metal hoop top right, part of the support bat appended thereto. The strongest visual element here is the trunctaed wheel. It''s an appealing image in many ways, but ultimately confusing and haphazard feeling to me.', '2004-12-30 02:38:34.000000', NULL, 1),
(1082667, 130579, 30861, '<td valign="top">Less DOF might work here. A little more pop on the lock, light-wise, would help... I donno, it just seems kind of blah, but it''s a nice sort of blah, if that makes sense?</td>', 'Less DOF might work here. A little more pop on the lock, light-wise, would help... I donno, it just seems kind of blah, but it''s a nice sort of blah, if that makes sense?', '2004-12-30 02:40:04.000000', NULL, 1),
(1082668, 130694, 30861, '<td valign="top">The truncation of the inner (orange) diameter of the upper wheel is extremely unfortunate. Ditto the "disappearing rivet" detail left. Image woudl benefit from cropping left and foregroudn both. Otherwise luscious, very tactile.</td>', 'The truncation of the inner (orange) diameter of the upper wheel is extremely unfortunate. Ditto the "disappearing rivet" detail left. Image woudl benefit from cropping left and foregroudn both. Otherwise luscious, very tactile.', '2004-12-30 02:42:31.000000', NULL, 1),
