(1082964, 130651, 25397, '<td valign="top">Very cool light on the wall behind the camera! The picture really casts the mood that the camera is old.</td>', 'Very cool light on the wall behind the camera! The picture really casts the mood that the camera is old.', '2004-12-30 11:52:24.000000', NULL, 1),
(1082965, 131295, 29799, '<td valign="top">That is so COOL!</td>', 'That is so COOL!', '2004-12-30 11:54:39.000000', NULL, 1),
