(1083815, 131199, 1202, '<td valign="top">Composition: 6, Nice set up.<br/>Technical: 4, Looks a bit oversharpened.<br/>Appeal: 6<br/>Challenge: 9<br/>Overall Calculated Average Score: 6</td>', 'Composition: 6, Nice set up.Technical: 4, Looks a bit oversharpened.Appeal: 6Challenge: 9Overall Calculated Average Score: 6', '2004-12-30 23:38:53.000000', NULL, 1),
(1083819, 131313, 1202, '<td valign="top">Composition: 5, Too centered for me and a diagonal would be good.<br/>Technical: 4, Looks a bit over sharpened. Also dust specs in BG could have been cloned out.<br/>Appeal: 6<br/>Challenge: 9<br/>Overall Calculated Average Score: 6</td>', 'Composition: 5, Too centered for me and a diagonal would be good.Technical: 4, Looks a bit over sharpened. Also dust specs in BG could have been cloned out.Appeal: 6Challenge: 9Overall Calculated Average Score: 6', '2004-12-30 23:40:52.000000', NULL, 1),
(1083825, 131243, 30861, '<td valign="top">It''s a lovely, pure mechanical object, but there''s a significant subject/ground conflict here, witht he handle getting lost in the treeline and the top of the pump tangent to the strong horizontal.</td>', 'It''s a lovely, pure mechanical object, but there''s a significant subject/ground conflict here, witht he handle getting lost in the treeline and the top of the pump tangent to the strong horizontal.', '2004-12-30 23:42:38.000000', NULL, 1),
