(1084923, 130707, 22748, '<td valign="top">Was this done in-camera? Nicely executed panning, if so. Kind of scary, actually, that would scare any kid, an angry horse with teeth bared charging at them at high speed... :) I like the colors in the shot, and the way the limited sharpness highlights the subject.</td>', 'Was this done in-camera? Nicely executed panning, if so. Kind of scary, actually, that would scare any kid, an angry horse with teeth bared charging at them at high speed... :) I like the colors in the shot, and the way the limited sharpness highlights the subject.', '2004-12-31 20:46:20.000000', NULL, 1),
(1084924, 131259, 22748, '<td valign="top">Awesome color!! I love the warm/cool contrast.</td>', 'Awesome color!! I love the warm/cool contrast.', '2004-12-31 20:46:48.000000', NULL, 1),
(1084929, 131192, 22748, '<td valign="top">Great color. A brilliant, simple, strong composition.</td>', 'Great color. A brilliant, simple, strong composition.', '2004-12-31 20:52:34.000000', NULL, 1),
