(1087818, 131356, 19831, '<td valign="top">Good composition. Nice selective desat, however in this case I think it draws attention to the frame and away from the main subject, the gears.</td>', 'Good composition. Nice selective desat, however in this case I think it draws attention to the frame and away from the main subject, the gears.', '2005-01-02 23:14:38.000000', NULL, 1),
(1087822, 131119, 19831, '<td valign="top">Interesting and creative. Nice perspective. Good job.</td>', 'Interesting and creative. Nice perspective. Good job.', '2005-01-02 23:18:12.000000', NULL, 1),
(1087825, 130932, 19831, '<td valign="top">Very nice lighting. Interesting perspective.</td>', 'Very nice lighting. Interesting perspective.', '2005-01-02 23:19:27.000000', NULL, 1),
(1087828, 131274, 22970, '<td valign="top">Very nice image. I like the close up of the engine wheels it gives it a very mechanical look and a focal point. I like your choice of B&amp;W and your POV. Great DOF and what I really like about this shot is even with outdoor [sun] lighting your highlights are not blown out, they are very smooth and eye appealing making the shadows interesting. Great Job 8!</td>', 'Very nice image. I like the close up of the engine wheels it gives it a very mechanical look and a focal point. I like your choice of B&W and your POV. Great DOF and what I really like about this shot is even with outdoor [sun] lighting your highlights are not blown out, they are very smooth and eye appealing making the shadows interesting. Great Job 8!', '2005-01-02 23:20:58.000000', NULL, 1),
(1087853, 130559, 22970, '<td valign="top">Very nice picture. I like the lighting and the true chrome look along with the reflection. Great focus.</td>', 'Very nice picture. I like the lighting and the true chrome look along with the reflection. Great focus.', '2005-01-02 23:34:44.000000', NULL, 1),
