INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1088794, 131173, 30342, '<td valign="top">I can''t even tell what this is.  Doesn''t have appeal.</td>', 'I can''t even tell what this is.  Doesn''t have appeal.', '2005-01-03 13:46:22.000000', NULL, 1),
(1088796, 130651, 30342, '<td valign="top">Too dark and out of focus.</td>', 'Too dark and out of focus.', '2005-01-03 13:47:06.000000', NULL, 1),
(1088798, 130370, 30342, '<td valign="top">The composition could have been better.  Looks too much like a snapshot.  Make the picture bigger next time too... I know people give lower scores for smaller pictures.</td>', 'The composition could have been better.  Looks too much like a snapshot.  Make the picture bigger next time too... I know people give lower scores for smaller pictures.', '2005-01-03 13:48:44.000000', NULL, 1),
(1088800, 131305, 30342, '<td valign="top">Just doesn''t appeal to me.  I''m sure it was difficult to capture but I probably would have taken the picture of it not in flight.</td>', 'Just doesn''t appeal to me.  I''m sure it was difficult to capture but I probably would have taken the picture of it not in flight.', '2005-01-03 13:49:53.000000', NULL, 1),
(1088801, 130813, 30342, '<td valign="top">White balance looks off.  Composition not too appealing... Put more thought into the challenges... I know it can be hard sometimes, but think about it more before you just grab the first thing in your house and shoot it.</td>', 'White balance looks off.  Composition not too appealing... Put more thought into the challenges... I know it can be hard sometimes, but think about it more before you just grab the first thing in your house and shoot it.', '2005-01-03 13:51:05.000000', NULL, 1),
(1088802, 131290, 30342, '<td valign="top">It''s hard to tell it''s a merry go round.  I would have scored it higher if I could see the whole thing.</td>', 'It''s hard to tell it''s a merry go round.  I would have scored it higher if I could see the whole thing.', '2005-01-03 13:51:41.000000', NULL, 1),
(1088803, 131161, 30342, '<td valign="top">It is mechanical, and you know how to blackout the background, but the subject is just not appealing at all.  I would put more thought into the challenge next time.</td>', 'It is mechanical, and you know how to blackout the background, but the subject is just not appealing at all.  I would put more thought into the challenge next time.', '2005-01-03 13:52:39.000000', NULL, 1),
