(1090177, 130691, 31443, '<td valign="top">Ok, I gave an 8 to another bottle opener because it was fantastic.....aren''t we a little overdoing it?<br/> <br/>...............<br/> <br/>I apologize for my comment and the low vote,  I actually thought this was another input from the same photo that actually won the contest! The models looked the same. Now after understanding the rules I see that only one photo from each participant is in the contest. I should have given a much higher score....sorry<br/><br/><i>Message edited by author 2005-01-05 05:54:57.</i></td>', 'Ok, I gave an 8 to another bottle opener because it was fantastic.....aren''t we a little overdoing it? ............... I apologize for my comment and the low vote,  I actually thought this was another input from the same photo that actually won the contest! The models looked the same. Now after understanding the rules I see that only one photo from each participant is in the contest. I should have given a much higher score....sorry', '2005-01-04 04:41:40.000000', '2005-01-05 05:54:57.000000', 1),
(1090178, 130998, 19831, '<td valign="top">Wow, is that an old meat grinder? My dad used to make the most awesome ham salad with one of those. Interesting perspective. Nice lighting. B/W works well in this case IMO. Bonus points for personal nostalgia sake.  :-)</td>', 'Wow, is that an old meat grinder? My dad used to make the most awesome ham salad with one of those. Interesting perspective. Nice lighting. B/W works well in this case IMO. Bonus points for personal nostalgia sake.  :-)', '2005-01-04 04:43:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1090179, 130269, 19831, '<td valign="top">Cute idea. Gave me a nice chuckle. Bonus points for humor!</td>', 'Cute idea. Gave me a nice chuckle. Bonus points for humor!', '2005-01-04 04:45:28.000000', NULL, 1),
(1090184, 130988, 31443, '<td valign="top">I will never whip eggs again :(</td>', 'I will never whip eggs again :(', '2005-01-04 04:57:40.000000', NULL, 1),
(1090185, 131048, 31443, '<td valign="top">Very nice</td>', 'Very nice', '2005-01-04 04:58:26.000000', NULL, 1),
(1090187, 131212, 30861, '<td valign="top">One feels that this image could have beens so much more... The colors are luscious, but the composition is lackluster. Given the POV you have chosen, this would be much stronger if you chopped a third of the image off from the top.</td>', 'One feels that this image could have beens so much more... The colors are luscious, but the composition is lackluster. Given the POV you have chosen, this would be much stronger if you chopped a third of the image off from the top.', '2005-01-04 05:03:11.000000', NULL, 1),
(1090189, 131255, 30861, '<td valign="top">Would be stronger if a quarter of the foregrounf were removed and the equivalent added to the top to feature the mechanism more.</td>', 'Would be stronger if a quarter of the foregrounf were removed and the equivalent added to the top to feature the mechanism more.', '2005-01-04 05:05:02.000000', NULL, 1),
(1090190, 130108, 30861, '<td valign="top">This is a luscious bridgeworks, looks like Boston''s new bridge? The compsoition is hurting the image though, as are the blown-out highlights. Take some foreground off, and give us more sky, and it would breathe better...</td>', 'This is a luscious bridgeworks, looks like Boston''s new bridge? The compsoition is hurting the image though, as are the blown-out highlights. Take some foreground off, and give us more sky, and it would breathe better...', '2005-01-04 05:06:46.000000', NULL, 1),
(1090191, 131261, 30861, '<td valign="top">The lighting on this is too obscure for me to accept. It works wellon the reel, but the rod is getting lost. Also, the yellow pinstripe on this one is way too agressive IMO.</td>', 'The lighting on this is too obscure for me to accept. It works wellon the reel, but the rod is getting lost. Also, the yellow pinstripe on this one is way too agressive IMO.', '2005-01-04 05:08:50.000000', NULL, 1),
(1090192, 130998, 30861, '<td valign="top">A fairly decent piece of "brutalism",  object as object, harsh and simple ansd straightforward. a little too contrasty, perhaps...</td>', 'A fairly decent piece of "brutalism",  object as object, harsh and simple ansd straightforward. a little too contrasty, perhaps...', '2005-01-04 05:10:12.000000', NULL, 1),
(1090193, 131117, 31443, '<td valign="top">I think fans are useful, specially when we have the "fee fow fum" spreading everywhere!</td>', 'I think fans are useful, specially when we have the "fee fow fum" spreading everywhere!', '2005-01-04 05:12:49.000000', NULL, 1),
(1090195, 131153, 7252, '<td valign="top">Strong image but seems out of focus without purpose.</td>', 'Strong image but seems out of focus without purpose.', '2005-01-04 05:16:41.000000', NULL, 1),
(1090196, 130269, 31443, '<td valign="top">Boys and their toys</td>', 'Boys and their toys', '2005-01-04 05:28:39.000000', NULL, 1),
(1090197, 130856, 31443, '<td valign="top">What is it with b/w photographs? They are either wonderful or just b/w I cannot make my mind up on this one</td>', 'What is it with b/w photographs? They are either wonderful or just b/w I cannot make my mind up on this one', '2005-01-04 05:33:04.000000', NULL, 1),
(1090198, 130101, 31443, '<td valign="top">I agree, like this image but cannot understand why that foot had to be in between frame and photo?</td>', 'I agree, like this image but cannot understand why that foot had to be in between frame and photo?', '2005-01-04 05:34:56.000000', NULL, 1),
(1090200, 130932, 31443, '<td valign="top">Image is nice but why the embroidery thread? ok ok colors are cool</td>', 'Image is nice but why the embroidery thread? ok ok colors are cool', '2005-01-04 05:38:27.000000', NULL, 1),
(1090201, 130729, 31443, '<td valign="top">Would have like to see this tractor whole</td>', 'Would have like to see this tractor whole', '2005-01-04 05:40:00.000000', NULL, 1),
(1090202, 131212, 31443, '<td valign="top">And how much does the machine cost? I like the colors but is this an advert?</td>', 'And how much does the machine cost? I like the colors but is this an advert?', '2005-01-04 05:41:46.000000', NULL, 1),
(1090203, 131154, 31443, '<td valign="top">A rare find indeed!</td>', 'A rare find indeed!', '2005-01-04 05:42:37.000000', NULL, 1),
(1090204, 131224, 29255, '<td valign="top">Nice idea, good execution. Composition might be better, now attention gets too centered due the only sharp area and then eye is competed into to directions by straight line into corner and colorful area to top. I''d also like a bit more depth of field.</td>', 'Nice idea, good execution. Composition might be better, now attention gets too centered due the only sharp area and then eye is competed into to directions by straight line into corner and colorful area to top. I''d also like a bit more depth of field.', '2005-01-04 05:43:28.000000', NULL, 1),
(1090206, 130471, 31443, '<td valign="top">Something about this image...barbwire, padlock, empty spaces, I like</td>', 'Something about this image...barbwire, padlock, empty spaces, I like', '2005-01-04 05:45:05.000000', NULL, 1),
(1090207, 130894, 31443, '<td valign="top">There is drama and then there is drama, too intense</td>', 'There is drama and then there is drama, too intense', '2005-01-04 05:46:35.000000', NULL, 1),
(1090208, 130732, 29255, '<td valign="top">Very nice feeling. Emits old. Shadows at right get perhaps a bit too green, but otherwise the color balance is marvellous. On all scales, this is image is not completely balanced, as the egg adds weights more to the right. Positioning this scale a bit to left from center doesn''t relieve the balance enough, but is clearly a try into that direction. I''d like to have the bird and the metal plate beneath her sharper.</td>', 'Very nice feeling. Emits old. Shadows at right get perhaps a bit too green, but otherwise the color balance is marvellous. On all scales, this is image is not completely balanced, as the egg adds weights more to the right. Positioning this scale a bit to left from center doesn''t relieve the balance enough, but is clearly a try into that direction. I''d like to have the bird and the metal plate beneath her sharper.', '2005-01-04 05:47:40.000000', NULL, 1),
(1090209, 130530, 29255, '<td valign="top">It feels like there''s too many windows to have the entire piece mechanical, and yes, the flash shoe, at least, helds a sign of electronics. The image is ok. The camera seems to be lifted from the surface, but the objective, even though is small, seems to touch, it drags a bit. So overall feeling is that the camera itself is light as a feater but accompanied glass keeps it near ground level. I like the back of camera, but don''t like burned bottom. Wignetting works, but there''s maybe a bit too much of it, gives quite negating effect at top corners.</td>', 'It feels like there''s too many windows to have the entire piece mechanical, and yes, the flash shoe, at least, helds a sign of electronics. The image is ok. The camera seems to be lifted from the surface, but the objective, even though is small, seems to touch, it drags a bit. So overall feeling is that the camera itself is light as a feater but accompanied glass keeps it near ground level. I like the back of camera, but don''t like burned bottom. Wignetting works, but there''s maybe a bit too much of it, gives quite negating effect at top corners.', '2005-01-04 05:52:43.000000', NULL, 1),
(1090211, 130917, 8666, '<td valign="top">Cool metal look</td>', 'Cool metal look', '2005-01-04 05:52:47.000000', NULL, 1),
(1090212, 131287, 8666, '<td valign="top">... or my grandfather''s computer :D</td>', '... or my grandfather''s computer :D', '2005-01-04 05:54:15.000000', NULL, 1),
(1090213, 130856, 29255, '<td valign="top">For BW this image is quite gray overall. W is reserved for skies and little detail at left rocks. The best portion is bottom right quadrant where the tones go well together. The feeling is that train needs to climb a bit, so with faster speed it would rock over poor photographer. Luckily there''s no sense of speed here, so the feeling transforms into idea of heavy weight cargo being pulled. Too bad the mechanical topic is slightly dismissed by trains facade highlights caused by electronics.</td>', 'For BW this image is quite gray overall. W is reserved for skies and little detail at left rocks. The best portion is bottom right quadrant where the tones go well together. The feeling is that train needs to climb a bit, so with faster speed it would rock over poor photographer. Luckily there''s no sense of speed here, so the feeling transforms into idea of heavy weight cargo being pulled. Too bad the mechanical topic is slightly dismissed by trains facade highlights caused by electronics.', '2005-01-04 05:56:28.000000', NULL, 1),
(1090214, 130932, 29255, '<td valign="top">Even though the use of colors, light  and composion is nice here, I''m hardly pushed to believe this thing isnt'' electronical.  For composition I''d like you to reconsider if you feel the big wheel with smaller wheel at the closer end of the Singer is the most important part. Now it''s greatness, inherent constrasty and location in frame all emphasises it''s meaning. I also believe it was your decision to use such a short focal length, but maybe you could reconsider longer now.</td>', 'Even though the use of colors, light  and composion is nice here, I''m hardly pushed to believe this thing isnt'' electronical.  For composition I''d like you to reconsider if you feel the big wheel with smaller wheel at the closer end of the Singer is the most important part. Now it''s greatness, inherent constrasty and location in frame all emphasises it''s meaning. I also believe it was your decision to use such a short focal length, but maybe you could reconsider longer now.', '2005-01-04 06:02:00.000000', NULL, 1),
(1090215, 131280, 8666, '<td valign="top">I had to look twice to see it, nice touch.</td>', 'I had to look twice to see it, nice touch.', '2005-01-04 06:02:17.000000', NULL, 1),
(1090216, 130622, 29255, '<td valign="top">The look and idea are nice, but still this image doesn''t get me ticking. Unfortunately I can''t say why.<br/> <br/>Some more light would have allowed the flames exposured well.</td>', 'The look and idea are nice, but still this image doesn''t get me ticking. Unfortunately I can''t say why. Some more light would have allowed the flames exposured well.', '2005-01-04 06:04:29.000000', NULL, 1),
(1090217, 131254, 29255, '<td valign="top">It''s hard to see what''s going on, so without other knowledge I might believe it''s some glass sphere with some weird reflections. Nice idea though, so I guess the execution needs to be worked a bit more.</td>', 'It''s hard to see what''s going on, so without other knowledge I might believe it''s some glass sphere with some weird reflections. Nice idea though, so I guess the execution needs to be worked a bit more.', '2005-01-04 06:06:33.000000', NULL, 1),
(1090218, 131283, 29255, '<td valign="top">More about trademark and rhythm than about title or topic. Nice lights.</td>', 'More about trademark and rhythm than about title or topic. Nice lights.', '2005-01-04 06:07:53.000000', NULL, 1),
(1090220, 130904, 29255, '<td valign="top">They do these electronically too these days, but I simply cannot see why. Odd feeling when the light or environment haev some blue and green parts. Shadow makes the bottom wheel look like it barely fits into the frame.</td>', 'They do these electronically too these days, but I simply cannot see why. Odd feeling when the light or environment haev some blue and green parts. Shadow makes the bottom wheel look like it barely fits into the frame.', '2005-01-04 06:10:03.000000', NULL, 1),
(1090224, 131260, 29255, '<td valign="top">Doesn''t feel too sharp. Your subject is nice, but I''m sure you could have got much more out of it. In addition putting the sled into some other position, to some other background, you might like to do it in some other part of day so that light would favor you a bit.</td>', 'Doesn''t feel too sharp. Your subject is nice, but I''m sure you could have got much more out of it. In addition putting the sled into some other position, to some other background, you might like to do it in some other part of day so that light would favor you a bit.', '2005-01-04 06:12:35.000000', NULL, 1),
(1090226, 130995, 29255, '<td valign="top">Very nice touch. Light is perfect and you''ve managed to get even some sparkle in some brilliant droplets. It feels so done, but still is elusive as it''s natural enough. Can''t say yet if that''s ribbon, but it''s good anyway.</td>', 'Very nice touch. Light is perfect and you''ve managed to get even some sparkle in some brilliant droplets. It feels so done, but still is elusive as it''s natural enough. Can''t say yet if that''s ribbon, but it''s good anyway.', '2005-01-04 06:16:31.000000', NULL, 1),
(1090227, 130844, 29255, '<td valign="top">Feels like there''s something to work on with the white balance. Nice composition though.</td>', 'Feels like there''s something to work on with the white balance. Nice composition though.', '2005-01-04 06:17:30.000000', NULL, 1),
(1090229, 131137, 29255, '<td valign="top">Cold tones fit, but light doesn''t seem good elsewhere than on leftmost leg. Background is horrible, but that you probably knew already.</td>', 'Cold tones fit, but light doesn''t seem good elsewhere than on leftmost leg. Background is horrible, but that you probably knew already.', '2005-01-04 06:19:16.000000', NULL, 1),
(1090231, 130963, 29255, '<td valign="top">The image is quite gray (or was before toning). Nice idea. I would have liked the metronome positioned closer to center, now it''s falling away. Highlight at after the rightmost hand could be good, but feels like it''s also too close to the border to be good now.</td>', 'The image is quite gray (or was before toning). Nice idea. I would have liked the metronome positioned closer to center, now it''s falling away. Highlight at after the rightmost hand could be good, but feels like it''s also too close to the border to be good now.', '2005-01-04 06:21:29.000000', NULL, 1),
(1090233, 131221, 29255, '<td valign="top">Great image if it was like this. Now it feels way overly saturated and contrasted. On the other hand, many people like candy colors. In any case the composition is nice, giving room for the background in balanced way.</td>', 'Great image if it was like this. Now it feels way overly saturated and contrasted. On the other hand, many people like candy colors. In any case the composition is nice, giving room for the background in balanced way.', '2005-01-04 06:23:28.000000', NULL, 1),
(1090237, 131293, 29255, '<td valign="top">There''s too much of everything. Too much of gray and way too much colors (feels oversaturated), too much of flurry and hussle. It very hard to say what''s the point of the image apart of "mechanical things attract others to the limit of chaos". Still, there''s lot to see here, so even if my eyes would have liked to skip I maintained my position over this for a moment.</td>', 'There''s too much of everything. Too much of gray and way too much colors (feels oversaturated), too much of flurry and hussle. It very hard to say what''s the point of the image apart of "mechanical things attract others to the limit of chaos". Still, there''s lot to see here, so even if my eyes would have liked to skip I maintained my position over this for a moment.', '2005-01-04 06:26:32.000000', NULL, 1),
(1090351, 131048, 16301, '<td valign="top">Nice golden color, I like the motion, it makes it more interesting...</td>', 'Nice golden color, I like the motion, it makes it more interesting...', '2005-01-04 08:45:27.000000', NULL, 1),
(1090352, 130995, 16301, '<td valign="top">Very well done, I would expect to see it in an ad. Excellent lighting...<br/> <br/>(please share your lighting setup after the challenge)</td>', 'Very well done, I would expect to see it in an ad. Excellent lighting... (please share your lighting setup after the challenge)', '2005-01-04 08:47:34.000000', NULL, 1),
(1090354, 131016, 16301, '<td valign="top">lol, very nice! I like the lighting, the background works well with it...</td>', 'lol, very nice! I like the lighting, the background works well with it...', '2005-01-04 08:49:02.000000', NULL, 1),
(1090355, 130950, 31485, '<td valign="top">fabulous blue tones on the sax... you get two thumbs up!</td>', 'fabulous blue tones on the sax... you get two thumbs up!', '2005-01-04 08:49:15.000000', NULL, 1),
(1090356, 130893, 16301, '<td valign="top">I like the moody lighting, the diagonal composition works well...</td>', 'I like the moody lighting, the diagonal composition works well...', '2005-01-04 08:50:24.000000', NULL, 1),
(1090358, 131221, 16301, '<td valign="top">I think you composed this very well, with enough of the chain and the other part in the background, well done!</td>', 'I think you composed this very well, with enough of the chain and the other part in the background, well done!', '2005-01-04 08:52:23.000000', NULL, 1),
(1090359, 130895, 3127, '<td valign="top">Great lighting</td>', 'Great lighting', '2005-01-04 08:53:12.000000', NULL, 1),
