(1090364, 130926, 3127, '<td valign="top">Omitting the hand may have decreased the distraction. Great photo, though.</td>', 'Omitting the hand may have decreased the distraction. Great photo, though.', '2005-01-04 08:55:07.000000', NULL, 1),
(1090365, 130963, 3127, '<td valign="top">Nice tones - great photo</td>', 'Nice tones - great photo', '2005-01-04 08:55:20.000000', NULL, 1),
