(1090367, 131279, 3127, '<td valign="top">Great contrasting colors</td>', 'Great contrasting colors', '2005-01-04 08:56:10.000000', NULL, 1),
(1090368, 131191, 3127, '<td valign="top">Beautiful depth.</td>', 'Beautiful depth.', '2005-01-04 08:56:35.000000', NULL, 1),
(1090371, 131274, 3127, '<td valign="top">I''ve always loved pictures of the mechanics of a train. Wonderful depth, just a tad too bright.</td>', 'I''ve always loved pictures of the mechanics of a train. Wonderful depth, just a tad too bright.', '2005-01-04 08:57:07.000000', NULL, 1),
(1090373, 130812, 3127, '<td valign="top">Great depth, great color use on the hinge. It really pops!</td>', 'Great depth, great color use on the hinge. It really pops!', '2005-01-04 08:57:47.000000', NULL, 1),
(1090374, 130990, 31485, '<td valign="top">that IS electrical, isn''t it?</td>', 'that IS electrical, isn''t it?', '2005-01-04 08:58:09.000000', NULL, 1),
