(1090376, 130986, 31485, '<td valign="top">poo on the name, mac</td>', 'poo on the name, mac', '2005-01-04 09:01:02.000000', NULL, 1),
(1090377, 131311, 31485, '<td valign="top">ummm.... yeah... ahhh, well, see, it''s just that it''s...well, it''s... ELECTRIC!!!</td>', 'ummm.... yeah... ahhh, well, see, it''s just that it''s...well, it''s... ELECTRIC!!!', '2005-01-04 09:01:59.000000', NULL, 1),
