(1090390, 131357, 20056, '<td valign="top">I like it!</td>', 'I like it!', '2005-01-04 09:15:41.000000', NULL, 1),
(1090436, 130699, 31229, '<td valign="top">Don''t all engines look like that?</td>', 'Don''t all engines look like that?', '2005-01-04 10:34:38.000000', NULL, 1),
