(1105816, 130794, 30049, '<td valign="top">Cool wine opener.  This shot could have benefited from more of a studio type look instead of the kitchen counter.  Kind of a yellowish cast from overhead indoor lights?</td>', 'Cool wine opener.  This shot could have benefited from more of a studio type look instead of the kitchen counter.  Kind of a yellowish cast from overhead indoor lights?', '2005-01-13 12:11:49.000000', NULL, 0),
(1106672, 130216, 26313, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by thewriterside:</b></div><hr/><i>To all of you with similar comments, I want to refer back to DPChallenge''s definition of "mechanical," which was something along the lines of "Something that doesn''t require electricity as means of operation..." Yes, to me "mechanical" is not a candle. I based it on DPChallenges definition, and wanted to be unique. I was under the impression that a concept of any art is to think outside of the box and express the rules in a new way- in your own way. I''m having trouble understanding why so many of you found this unacceptable. Maybe it''s because this was the first challenege I participated in? </i></td></tr></table> <br/>I don''t take that as a <i>definition</i> of mechanical, I take it as a <i>restriction</i> on mechanical. Some of us even distinguish between electronic and electrical, thus there are many items that do rely on electricity that <i>do</i> fit the challenge. Since this is kind of a grey area for many people though, especially for those without much of a technical background, it is a good idea to avoid electricity altogether in order to avoid "doesn''t meet challenge" type comments. My point is, yes, there are certainly different interpretations of the challenge, but put yourself in the voters'' shoes, and think to yourself, "Does this photo say ''Mechanical!'' to me?"  If the answer is no, then you might want to rethink your submission. In terms of thinking outside the box, that''s fine, but if the end result doesn''t embody the essence of the challenge, you''ll take a hit in voting, even if it is technically a good photo.<br/><br/><i>Message edited by author 2005-01-13 21:13:49.</i></td>', 'Originally posted by thewriterside:To all of you with similar comments, I want to refer back to DPChallenge''s definition of "mechanical," which was something along the lines of "Something that doesn''t require electricity as means of operation..." Yes, to me "mechanical" is not a candle. I based it on DPChallenges definition, and wanted to be unique. I was under the impression that a concept of any art is to think outside of the box and express the rules in a new way- in your own way. I''m having trouble understanding why so many of you found this unacceptable. Maybe it''s because this was the first challenege I participated in?  I don''t take that as a definition of mechanical, I take it as a restriction on mechanical. Some of us even distinguish between electronic and electrical, thus there are many items that do rely on electricity that do fit the challenge. Since this is kind of a grey area for many people though, especially for those without much of a technical background, it is a good idea to avoid electricity altogether in order to avoid "doesn''t meet challenge" type comments. My point is, yes, there are certainly different interpretations of the challenge, but put yourself in the voters'' shoes, and think to yourself, "Does this photo say ''Mechanical!'' to me?"  If the answer is no, then you might want to rethink your submission. In terms of thinking outside the box, that''s fine, but if the end result doesn''t embody the essence of the challenge, you''ll take a hit in voting, even if it is technically a good photo.', '2005-01-13 21:12:33.000000', '2005-01-13 21:13:49.000000', 0),
(1108479, 130238, 22641, '<td valign="top">Welcome and nice technique to control the light :) Its my first ever post on DPC as well. Good Luck</td>', 'Welcome and nice technique to control the light :) Its my first ever post on DPC as well. Good Luck', '2005-01-15 00:36:54.000000', NULL, 0),
(1115282, 130794, 30818, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by glad2badad:</b></div><hr/><i> Cool wine opener.  This shot could have benefited from more of a studio type look instead of the kitchen counter.  Kind of a yellowish cast from overhead indoor lights? </i></td></tr></table> <br/> <br/>Acutally, there is a window to the left and it was the sunlight coming in.  I learned from this shot about the need to white balance.</td>', 'Originally posted by glad2badad: Cool wine opener.  This shot could have benefited from more of a studio type look instead of the kitchen counter.  Kind of a yellowish cast from overhead indoor lights?   Acutally, there is a window to the left and it was the sunlight coming in.  I learned from this shot about the need to white balance.', '2005-01-17 17:58:16.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1132049, 131327, 9939, '<td valign="top">Yep, I would have had a hard time with this one too. Having never seen one of these (I know, how weird is that), I wouldn''t have been able to figure out what was going on here. I do like the bright blue background against the other colors here.</td>', 'Yep, I would have had a hard time with this one too. Having never seen one of these (I know, how weird is that), I wouldn''t have been able to figure out what was going on here. I do like the bright blue background against the other colors here.', '2005-01-25 23:12:43.000000', NULL, 0),
(1132215, 131327, 656, '<td valign="top">Took me a bit of time to work out what was going on here.  Everything seems crammed in to the frame, with 4 or 5 distinct compositional elements battling for attention and control.  Not too sure that it is as strong as a result of that clutter.<br/> <br/>It is certainly an interesting object and the bright red colours with the blue background also have potential - but then you''ve got the apples and the stalks and peel and the metal all clustering in.<br/> <br/>White balance appears a bit warm, though you mention you were experimenting with them.</td>', 'Took me a bit of time to work out what was going on here.  Everything seems crammed in to the frame, with 4 or 5 distinct compositional elements battling for attention and control.  Not too sure that it is as strong as a result of that clutter. It is certainly an interesting object and the bright red colours with the blue background also have potential - but then you''ve got the apples and the stalks and peel and the metal all clustering in. White balance appears a bit warm, though you mention you were experimenting with them.', '2005-01-26 00:11:40.000000', NULL, 0),
(1133609, 130569, 31092, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by dartompkins:</b></div><hr/><i> I like the idea and the simplicity, but I think a shot like this has to be technically perfect since it is so simple.  The focus is a bit too soft and lighting a bit too harsh for my taste. </i></td></tr></table> <br/> <br/>This was before I discovered the unsharp mask. Somehow when I have to resize my pictures to fit the resolution limits the all look blurry when they are not. Any suggestions?<br/> <br/>Jeff</td>', 'Originally posted by dartompkins: I like the idea and the simplicity, but I think a shot like this has to be technically perfect since it is so simple.  The focus is a bit too soft and lighting a bit too harsh for my taste.   This was before I discovered the unsharp mask. Somehow when I have to resize my pictures to fit the resolution limits the all look blurry when they are not. Any suggestions? Jeff', '2005-01-26 15:29:14.000000', NULL, 0),
